import React, { useState, useCallback } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { DragDropContext, Droppable, Draggable, DropResult } from '@hello-pangea/dnd';
import { ShoppingItem } from '../types/types';
import ShoppingItemComponent from './ShoppingItemComponent';
import AddItemForm from './AddItemForm';
import CommonFoodSupplies, { FoodSupply } from './CommonFoodSupplies';
import './ShoppingList.css';

interface ShoppingListProps {
  listName?: string;
}

const ShoppingList: React.FC<ShoppingListProps> = ({ listName = 'My Shopping List' }) => {
  const [items, setItems] = useState<ShoppingItem[]>([]);

  const addItem = useCallback((name: string, quantity: number, price: number, category?: string) => {
    const newItem: ShoppingItem = {
      id: uuidv4(),
      name,
      quantity,
      price,
      completed: false,
      category,
    };
    setItems(prev => [...prev, newItem]);
  }, []);

  const updateItem = useCallback((id: string, updates: Partial<ShoppingItem>) => {
    setItems(prev => prev.map(item => 
      item.id === id ? { ...item, ...updates } : item
    ));
  }, []);

  const deleteItem = useCallback((id: string) => {
    setItems(prev => prev.filter(item => item.id !== id));
  }, []);

  const toggleComplete = useCallback((id: string) => {
    setItems(prev => prev.map(item => 
      item.id === id ? { ...item, completed: !item.completed } : item
    ));
  }, []);

  const clearCompleted = useCallback(() => {
    setItems(prev => prev.filter(item => !item.completed));
  }, []);

  const onDragEnd = useCallback((result: DropResult) => {
    if (!result.destination) {
      return;
    }

    // Handle drag from common foods to shopping list
    if (result.source.droppableId === 'common-foods' && result.destination.droppableId === 'shopping-list') {
      const draggedId = result.draggableId.replace('common-', '');
      
      // Common foods data - should match the data in CommonFoodSupplies
      const commonFoods = [
        { id: 'tomatoes', name: 'Tomatoes', category: 'Vegetables', defaultPrice: 3.99 },
        { id: 'potatoes', name: 'Potatoes', category: 'Vegetables', defaultPrice: 2.49 },
        { id: 'onions', name: 'Onions', category: 'Vegetables', defaultPrice: 1.99 },
        { id: 'carrots', name: 'Carrots', category: 'Vegetables', defaultPrice: 1.79 },
        { id: 'lettuce', name: 'Lettuce', category: 'Vegetables', defaultPrice: 2.29 },
        { id: 'bell-peppers', name: 'Bell Peppers', category: 'Vegetables', defaultPrice: 3.49 },
        { id: 'apples', name: 'Apples', category: 'Fruits', defaultPrice: 3.99 },
        { id: 'bananas', name: 'Bananas', category: 'Fruits', defaultPrice: 1.49 },
        { id: 'oranges', name: 'Oranges', category: 'Fruits', defaultPrice: 2.99 },
        { id: 'grapes', name: 'Grapes', category: 'Fruits', defaultPrice: 4.49 },
        { id: 'milk', name: 'Milk', category: 'Dairy', defaultPrice: 3.29 },
        { id: 'eggs', name: 'Eggs', category: 'Dairy', defaultPrice: 2.99 },
        { id: 'cheese', name: 'Cheese', category: 'Dairy', defaultPrice: 4.99 },
        { id: 'butter', name: 'Butter', category: 'Dairy', defaultPrice: 3.79 },
        { id: 'chicken', name: 'Chicken Breast', category: 'Meat', defaultPrice: 8.99 },
        { id: 'ground-beef', name: 'Ground Beef', category: 'Meat', defaultPrice: 6.99 },
        { id: 'bread', name: 'Bread', category: 'Bakery', defaultPrice: 2.49 },
        { id: 'rice', name: 'Rice', category: 'Pantry', defaultPrice: 3.99 },
        { id: 'pasta', name: 'Pasta', category: 'Pantry', defaultPrice: 1.99 },
        { id: 'olive-oil', name: 'Olive Oil', category: 'Pantry', defaultPrice: 5.99 },
      ];
      
      const foodItem = commonFoods.find(food => food.id === draggedId);
      if (foodItem) {
        // Check if item already exists in shopping list
        const existingItem = items.find(item => item.name.toLowerCase() === foodItem.name.toLowerCase());
        
        if (existingItem) {
          // If exists, increase quantity
          updateItem(existingItem.id, { quantity: existingItem.quantity + 1 });
        } else {
          // If doesn't exist, add new item
          const newItem: ShoppingItem = {
            id: uuidv4(),
            name: foodItem.name,
            quantity: 1,
            price: foodItem.defaultPrice,
            completed: false,
            category: foodItem.category,
          };
          
          const newItems = Array.from(items);
          newItems.splice(result.destination.index, 0, newItem);
          setItems(newItems);
        }
      }
      return;
    }

    // Handle reordering within shopping list
    if (result.source.droppableId === 'shopping-list' && result.destination.droppableId === 'shopping-list') {
      const newItems = Array.from(items);
      const [reorderedItem] = newItems.splice(result.source.index, 1);
      newItems.splice(result.destination.index, 0, reorderedItem);
      setItems(newItems);
    }
  }, [items, updateItem]);

  const totalCost = items.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const completedItems = items.filter(item => item.completed).length;

  return (
    <div className="shopping-list-container">
      <div className="main-content">
        <div className="header">
          <h1>{listName}</h1>
          <div className="stats">
            <span className="total-cost">Total: ${totalCost.toFixed(2)}</span>
            <span className="item-count">{completedItems}/{items.length} completed</span>
          </div>
        </div>

        <AddItemForm onAddItem={addItem} />

        <div className="actions">
          {items.some(item => item.completed) && (
            <button 
              className="clear-completed-btn"
              onClick={clearCompleted}
            >
              Clear Completed
            </button>
          )}
        </div>

        <DragDropContext onDragEnd={onDragEnd}>
          <div className="lists-container">
            <div className="shopping-list-section">
              <Droppable droppableId="shopping-list">
                {(provided, snapshot) => (
                  <div
                    {...provided.droppableProps}
                    ref={provided.innerRef}
                    className={`items-container ${snapshot.isDraggingOver ? 'dragging-over' : ''}`}
                  >
                    {items.length === 0 ? (
                      <div className="empty-state">
                        <p>Your shopping list is empty</p>
                        <p>Add items above or drag from the common foods →</p>
                      </div>
                    ) : (
                      items.map((item, index) => (
                        <Draggable key={item.id} draggableId={item.id} index={index}>
                          {(provided, snapshot) => (
                            <div
                              ref={provided.innerRef}
                              {...provided.draggableProps}
                              className={`draggable-item ${snapshot.isDragging ? 'dragging' : ''}`}
                            >
                              <ShoppingItemComponent
                                item={item}
                                onUpdate={updateItem}
                                onDelete={deleteItem}
                                onToggleComplete={toggleComplete}
                                dragHandleProps={provided.dragHandleProps}
                              />
                            </div>
                          )}
                        </Draggable>
                      ))
                    )}
                    {provided.placeholder}
                  </div>
                )}
              </Droppable>
            </div>
            
            <div className="sidebar">
              <CommonFoodSupplies />
            </div>
          </div>
        </DragDropContext>
      </div>
    </div>
  );
};

export default ShoppingList;
